EXPECTED = ["BZ-029","BZ-030","BZ-031","BZ-032","BZ-033","BZ-034","BZ-035","BZ-036","BZ-037","BZ-038","BZ-039","BZ-040","BZ-041","BZ-042","BZ-104","BZ-105","BZ-301","BZ-302","BZ-303","BZ-304",
"DT-001","DT-002","DT-003","DT-004","DT-005","DT-006","DT-007","LR-001","LR2-013","LR2-014","LR2-015","LR2-016","LR2-017","LR2-018","LR2-019","LR2-020","LR2-021","LR2-022","LR2-023","LR2-024",
"LR3-002","LR3-004","LR3-006","LR3-008","LR3-010","LR3-101","LR3-104","LR3-107","LR3-110","LR3-112","LR3-114","LR3-116","LY-001","LY-002","LY-003","LY-004","LY-005","LY-006","LY-007","LY-008"]
assert len(DATA) == 60, len(DATA)
ids = [d[0] for d in DATA]
assert sorted(ids) == sorted(EXPECTED), set(ids) ^ set(EXPECTED)
os.makedirs(OUT, exist_ok=True)
total = 0
for cid, first, pred, basis_extra, conf, trig in DATA:
    obj = {"case_id": cid, "prediction_text": pred,
           "basis": first + "。" + basis_extra,
           "confidence": conf, "trigger": trig}
    p = os.path.join(OUT, cid + ".json")
    with open(p, "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
    total += os.path.getsize(p)
# 逐件回读校验（只按本批id清单）
ok = 0; sizes = []
for cid in EXPECTED:
    p = os.path.join(OUT, cid + ".json")
    d = json.load(open(p, encoding="utf-8"))
    assert d["case_id"] == cid and d["prediction_text"] and d["basis"] and 0 <= d["confidence"] <= 1
    assert set(d["trigger"]) == {"changed_main","reserve_used","disputed","reason"}
    ok += 1; sizes.append(os.path.getsize(p))
ly = [d for d in DATA if d[0].startswith(("DT-","LY-"))]
print("written", ok, "total_bytes", total)
print("liuyao_trigger_counts",
      "changed_main", sum(1 for d in ly if d[5]["changed_main"]),
      "reserve_used", sum(1 for d in ly if d[5]["reserve_used"]),
      "disputed", sum(1 for d in ly if d[5]["disputed"]))
print("sizes", sizes)
